<template>
  <el-dialog :model-value="open" @update:model-value="emit('update:open',$event)" class="uranium-archive-dialog" width="min(1280px,96vw)" top="5vh" append-to-body destroy-on-close :show-close="false" :aria-label="`${data?.node.name || '供应链'}节点档案`">
    <template #header><header class="archive-header"><div><div class="archive-breadcrumb">铀供应链 <span>/</span> {{ zoneLabel }} <span>/</span> 节点档案</div><h2>{{ data?.node.name || '正在加载节点资料' }} <span v-if="data" class="archive-kind">{{ data.node.kind }}</span></h2></div><div class="archive-actions"><el-button v-if="data" text @click="download">导出档案</el-button><button @click="emit('update:open',false)" class="archive-close" aria-label="关闭节点档案">×</button></div></header></template>
    <div v-if="error" class="archive-message" role="alert">{{ error }}<el-button @click="load">重新加载</el-button></div>
    <div v-else v-loading="loading" class="archive-body">
      <aside class="archive-sidebar"><el-input v-model="search" clearable placeholder="在该节点内搜索资料" aria-label="搜索节点资料"/><div class="sidebar-caption">资料目录 <span>{{ totalCount }} 条</span></div><nav aria-label="节点资料分类"><button v-for="section in sections" :key="section.id" :class="{active:active===section.id}" @click="choose(section.id)"><span class="section-number">{{ section.number }}</span><span>{{ section.label }}</span><small>{{ section.count }}</small></button></nav><div class="archive-aside-note"><span>资料口径</span><p>按来源、年份与适用范围记录。实际交易、合同安排与模型规则分别保留依据。</p></div></aside>
      <main ref="content" class="archive-content">
        <template v-if="data && current"><div class="section-title"><div><small>{{ current.number }} / NODE DOSSIER</small><h3>{{ current.label }}</h3></div><span>{{ current.count }} 条资料</span></div>
          <p v-if="active==='overview'" class="section-intro">{{ data.node.subtitle || '沿供应链环节查看政策、事件、业务关系及其来源。' }}</p>
          <div v-if="active==='overview'" class="archive-stats"><button v-for="stat in stats" :key="stat.id" @click="choose(stat.id)"><strong>{{ stat.count }}</strong><span>{{ stat.label }}</span><i>↗</i></button></div>
          <section v-if="active==='china'&&filteredTrade.length" class="trade-section"><div class="trade-toolbar"><div><strong>中国报告的进口记录</strong><p>WITS 页面显示精度 · 商品重量 kg，与铀金属量 tU 区分。</p></div><el-select v-model="tradeYear" size="small" aria-label="选择贸易年份"><el-option v-for="year in years" :key="year" :label="`${year}年`" :value="year"/></el-select><el-select v-model="product" size="small" aria-label="选择贸易产品"><el-option v-for="p in products" :key="p.id" :label="p.label" :value="p.id"/></el-select></div>
            <div v-if="tradeRows.length" class="trade-table-scroll"><table class="trade-table"><thead><tr><th>来源国家</th><th>数量 / kg</th><th v-if="hasShare">该税目进口量占比</th><th>贸易额 / USD</th><th>来源</th></tr></thead><tbody><tr v-for="row in tradeRows" :key="`${row.year}-${row.product}-${row.country_id}`"><td><strong>{{ row.country }}</strong><small>HS {{ row.product }}</small></td><td class="numeric">{{ number(row.quantity) }}</td><td v-if="hasShare"><div v-if="row.share!=null" class="share-cell"><span>{{ number(row.share) }}%</span><div><i :style="{width:Math.max(row.share,1)+'%'}"/></div></div></td><td class="numeric">{{ row.value>0?number(row.value):'' }}</td><td><a v-if="safeUrl(row.url)" :href="row.url" target="_blank" rel="noopener noreferrer">WITS ↗</a></td></tr></tbody></table></div><p v-else class="search-empty">当前筛选下没有可展示的记录。</p><div class="trade-note">统计范围：中国申报进口 · {{ tradeYear }}年 · HS {{ product }}（{{ productName }}）。占比仅在全国该税目总量可用时展示。WITS 与 UN Comtrade 同源；国家级统计不分摊至具体企业。</div></section>
          <div v-if="active==='overview'&&neighbors.length" class="neighbor-section"><h4>前后级节点 <span>供应链角色关系</span></h4><div class="neighbor-list"><button v-for="item in neighbors" :key="item.id+item.direction" @click="emit('navigate',item.id)"><small>{{ item.direction }}</small><span>{{ item.name }}</span><i>↗</i></button></div></div>
          <div :class="['archive-cards',{'timeline-cards':active==='history','compact-cards':['ontology','rules'].includes(active)}]"><article v-for="(item,index) in visibleItems" :key="`${active}-${index}`" class="archive-card"><div class="card-head"><span v-if="item.date" class="card-date">{{ item.date }}</span><span v-if="item.status" class="card-status">{{ label(item.status) }}</span></div><h4>{{ label(item.title) }}</h4><p v-if="item.summary" class="card-summary">{{ label(item.summary) }}</p><dl v-if="item.fields?.some(f=>hasValue(f.value))"><template v-for="f in item.fields.filter(f=>hasValue(f.value))" :key="f.label"><dt>{{ f.label }}</dt><dd>{{ label(f.value) }}</dd></template></dl><footer v-if="item.source||item.url"><span v-if="item.source" :title="item.source">{{ item.source }}</span><a v-if="safeUrl(item.url)" :href="item.url" target="_blank" rel="noopener noreferrer">查看原始来源 ↗</a></footer></article></div>
          <button v-if="filteredItems.length>limit" class="load-more" @click="limit+=24">继续查看 {{ Math.min(24,filteredItems.length-limit) }} 条资料 <span>共 {{ filteredItems.length }} 条</span></button>
          <div v-if="!filteredItems.length&&!(active==='china'&&filteredTrade.length)" class="search-empty">当前搜索下没有匹配资料，请切换目录或调整关键词。</div>
        </template><p v-else-if="data" class="search-empty">没有匹配的资料，请调整搜索关键词。</p>
      </main>
    </div>
    <template #footer><div class="archive-footer"><span>来源可追溯 · 历史记录保留披露时间</span><span>{{ data?.node.name || '节点资料' }} <b>·</b> 铀供应链领域模型</span></div></template>
  </el-dialog>
</template>

<script setup>
import { computed, ref, watch } from 'vue'
import { getUraniumNodeArchive } from '@/api/uraniumDomainArchive'
const props=defineProps({open:Boolean,nodeId:{type:String,default:''},network:{type:Object,default:null},initialSection:{type:String,default:'overview'}}),emit=defineEmits(['update:open','navigate'])
const data=ref(null),error=ref(''),loading=ref(false),active=ref('overview'),search=ref(''),limit=ref(24),content=ref(null),tradeYear=ref(null),product=ref('284410')
let requestId=0
const hasValue=value=>value!==null&&value!==undefined&&value!==''
const safeUrl=url=>typeof url==='string'&&(/^https?:\/\//i.test(url)||/^\/SCnet\/uraniumKnowledge\/documents\/[a-zA-Z0-9_-]+\/file$/.test(url))
const number=value=>new Intl.NumberFormat('zh-CN',{maximumFractionDigits:3}).format(value)
const translations={COUNTRY:'国家',COMPANY:'企业',MINE:'矿山',DEPOSIT:'矿床',JOINT_VENTURE:'合资企业',PROCESSING_FACILITY:'加工设施',BORDER_CROSSING:'边境口岸',RAIL_TERMINAL:'铁路终端',PORT:'港口',STORAGE:'仓储',RECEIVING_NODE:'接收节点',TRANSIT_NODE:'中转节点',ROAD_TERMINAL:'道路终端',DIRECT:'直接公开依据',INDIRECT:'间接公开依据',VERIFIED:'库内已核验',VERIFIED_PUBLIC_ENTITY:'公开主体',PARTIALLY_VERIFIED:'部分字段核验',HISTORICAL_ACTUAL:'历史实际值',RUNTIME:'模型规则',direct_historical:'有历史对华交付记录',shipment_historical:'有历史对华启运记录',contract_only:'有对华合同依据',not_verified:'尚未证实对华交付',customs_and_services:'有历史海关申报及核燃料服务记录',service_only:'核燃料服务合作',materials_historical:'有历史澳方义务核材料转移记录',trace_observation:'微量海关记录',disputed_observation:'进口申报与镜像统计存在差异',POINT_IN_TIME_SNAPSHOT:'时点资源记录',uranium_production:'铀产量',uranium_producer:'铀生产',mine_operator:'矿山运营',fuel_services:'燃料服务',actual_annual_production:'年度实际产量',reported:'公开披露'}
const label=value=>{if(Array.isArray(value))return value.map(label).join(' · ');if(value&&typeof value==='object')return Object.entries(value).map(([k,v])=>`${k}：${label(v)}`).join('；');return translations[String(value)]||String(value??'')}
const hit=item=>!search.value.trim()||JSON.stringify(item).toLowerCase().includes(search.value.trim().toLowerCase())
const filteredTrade=computed(()=>(data.value?.trade||[]).filter(hit))
const sections=computed(()=>(data.value?.sections||[]).map(s=>({...s,count:s.items.filter(hit).length+(s.id==='china'?filteredTrade.value.length:0)})).filter(s=>s.count>0))
const current=computed(()=>sections.value.find(s=>s.id===active.value))
const totalCount=computed(()=>sections.value.reduce((n,s)=>n+s.count,0))
const filteredItems=computed(()=>(current.value?.items||[]).filter(hit))
const visibleItems=computed(()=>filteredItems.value.slice(0,limit.value))
const stats=computed(()=>sections.value.filter(s=>['china','entities','policies','history'].includes(s.id)))
const zoneLabel=computed(()=>({supply:'供应侧',bridge:'连接与服务',demand:'需求侧',event:'外部事件'}[data.value?.node.zone]||'节点资料'))
const neighbors=computed(()=>{const byId=new Map((props.network?.nodes||[]).map(n=>[n.id,n]));return (data.value?.connections||[]).map(e=>{const upstream=e.target===props.nodeId,id=upstream?e.source:e.target;return {id,name:byId.get(id)?.name||id,direction:upstream?'前级':'后级'}})})
const years=computed(()=>[...new Set(filteredTrade.value.map(r=>r.year))].sort((a,b)=>b-a))
const allProducts=[{id:'284410',label:'天然铀及其化合物'},{id:'261210',label:'铀矿石及精矿'},{id:'284420',label:'浓缩铀 / 钚相关物项'}]
const products=computed(()=>allProducts.filter(p=>filteredTrade.value.some(r=>r.product===p.id&&r.year===tradeYear.value)))
const productName=computed(()=>allProducts.find(p=>p.id===product.value)?.label||product.value)
const tradeRows=computed(()=>filteredTrade.value.filter(r=>r.year===tradeYear.value&&r.product===product.value))
const hasShare=computed(()=>tradeRows.value.some(r=>r.share!=null))
function choose(id){active.value=id;limit.value=24;content.value?.scrollTo({top:0})}
async function load(){if(!props.open||!props.nodeId)return;const id=++requestId;loading.value=true;error.value='';data.value=null;search.value='';active.value=props.initialSection;limit.value=24;try{const result=await getUraniumNodeArchive(props.nodeId);if(id!==requestId)return;data.value=result;tradeYear.value=years.value[0]||null;product.value=products.value.find(p=>p.id==='284410')?.id||products.value[0]?.id||'284410';content.value?.scrollTo({top:0})}catch{if(id===requestId)error.value='节点资料暂时无法加载，请重试。'}finally{if(id===requestId)loading.value=false}}
function download(){const blob=new Blob([JSON.stringify(data.value,null,2)],{type:'application/json;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`${data.value.node.name}-节点档案.json`;a.click();URL.revokeObjectURL(url)}
watch(()=>[props.open,props.nodeId],()=>{if(props.open)load();else requestId++})
watch(sections,list=>{if(!list.some(s=>s.id===active.value)&&list.length)choose(list[0].id)})
watch(years,list=>{if(!list.includes(tradeYear.value))tradeYear.value=list[0]||null})
watch(products,list=>{if(!list.some(p=>p.id===product.value))product.value=list[0]?.id||'284410'})
watch(search,()=>{limit.value=24})
</script>

