.uranium-archive-dialog{padding:0!important;border-radius:14px!important;overflow:hidden;--el-dialog-margin-top:5vh}.uranium-archive-dialog .el-dialog__header,.uranium-archive-dialog .el-dialog__footer{padding:0!important;margin:0!important}.uranium-archive-dialog .el-dialog__body{padding:0!important}.uranium-archive-dialog .el-loading-mask{border-radius:0}
</style>
